/* ===== 허브 게임 모듈: 점프 런 (run) ===== */
HUBREG((function(){
function runGoal(){const v=+(store.get('runGoal')||25);return [15,20,25,30].includes(v)?v:25;}
function runCoupon(kind){const p=RUN_PRIZES[kind]||RUN_PRIZES.cheese,sv=(COUPONS||[]).find(c=>c.id===p.id)||{};return{id:p.id,name:p.name,prefix:sv.prefix||p.prefix,img:sv.img||null,codeY:sv.codeY,codeSize:sv.codeSize,codeColor:sv.codeColor,on:true};}
const RUN_PRIZES={cheese:{id:'cheese',name:'치즈볼 2EA',prefix:'cb'},cola:{id:'drink',name:'캔음료 1EA',prefix:'dk'},shrimp:{id:'shrimp',name:'버터플라이 새우 3EA',prefix:'sh'}};
let RUN_RES=null;
function wordArt(str,x,y,size){
 const f="900 "+size+"px 'Black Han Sans','Noto Sans KR',sans-serif";ctx.save();ctx.font=f;ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineJoin='round';
 for(let i=10;i>=1;i--){ctx.fillStyle='#2b1d3a';ctx.fillText(str,x+i*0.5,y+i*1.0);}           /* 아래로 두께감 */
 ctx.lineWidth=size*0.16;ctx.strokeStyle='#2b1d3a';ctx.strokeText(str,x,y);
 const g=ctx.createLinearGradient(0,y-size*0.48,0,y+size*0.48);g.addColorStop(0,'#fff6c8');g.addColorStop(0.35,'#ffd84a');g.addColorStop(0.7,'#ffab2e');g.addColorStop(1,'#ff7f1f');
 ctx.fillStyle=g;ctx.fillText(str,x,y);
 ctx.restore();}
function ribbon(str,x,y,w,h,fs2){
 ctx.save();ctx.lineJoin='round';ctx.lineWidth=6;ctx.strokeStyle='#2b1d3a';
 for(const s2 of[-1,1]){ctx.beginPath();ctx.moveTo(x+s2*(w/2-10),y-h*0.32);ctx.lineTo(x+s2*(w/2+38),y-h*0.32);ctx.lineTo(x+s2*(w/2+20),y+h*0.12);ctx.lineTo(x+s2*(w/2+38),y+h*0.56);ctx.lineTo(x+s2*(w/2-10),y+h*0.56);ctx.closePath();ctx.fillStyle='#a3152f';ctx.fill();ctx.stroke();}
 rr(x-w/2,y-h/2,w,h,14);const g=ctx.createLinearGradient(0,y-h/2,0,y+h/2);g.addColorStop(0,'#ff5a6e');g.addColorStop(1,'#c91f45');ctx.fillStyle=g;ctx.fill();ctx.stroke();
 ctx.restore();txt(str,x,y+2,fs2,'#fff','#2b1d3a',8);}
function drawIntro(){
 RUNX.intro(ctx,W,H,t);
 const by=Math.sin(t*1.8)*6;
 ctx.save();ctx.translate(640,92);ctx.rotate(-0.03);rr(-92,-30,184,60,30);ctx.fillStyle='#e63946';ctx.fill();ctx.lineWidth=6;ctx.strokeStyle='#2b1d3a';ctx.stroke();ctx.restore();
 txt('EVENT',640,94,40,'#fff','#2b1d3a',8);
 wordArt('페리치킨런',640,232+by,172);
 ribbon('재료를 모아 이벤트 게이지를 가득 채워요!',640,372,690,74,38);
 const fy=Math.sin(t*2.4)*10,gl=0.5+0.5*Math.sin(t*4);
 ctx.save();ctx.translate(640,500+fy);ctx.shadowColor='rgba(255,214,102,'+(0.5+gl*0.5)+')';ctx.shadowBlur=20+gl*25;
 txt('START',0,0,112,'#fff','#e63946',16);ctx.restore();
 txt('화면을 터치해 주세요',640,606+fy*0.6,38,'#fff','#1d3557',8);
}

/* 보상 화면: 바구니 든 페리 → 바구니가 확대되며 별만 남음 → 별이 돌다가 선물 상자로 */
function starPath(r){ctx.beginPath();for(let i=0;i<10;i++){const q=i%2?r*0.43:r,a=-Math.PI/2+i*Math.PI/5;ctx.lineTo(q*Math.cos(a),q*Math.sin(a));}ctx.closePath();}
function drawCounts(y){const c=(RUN_RES&&RUN_RES.cnt)||{cheese:0,cola:0,shrimp:0},best=RUN_RES&&RUN_RES.best;['cheese','cola','shrimp'].forEach((k,i)=>{const x=640+(i-1)*230,im=RUNX.itemImg(k);ctx.save();rr(x-100,y-40,200,80,40);ctx.fillStyle=k===best?'rgba(255,232,140,.95)':'rgba(255,253,247,.92)';ctx.fill();ctx.lineWidth=5;ctx.strokeStyle='#2b1d3a';ctx.stroke();ctx.restore();if(im&&im.complete){const s=58/Math.max(im.naturalWidth,im.naturalHeight);ctx.drawImage(im,x-82,y-im.naturalHeight*s/2,im.naturalWidth*s,im.naturalHeight*s);}txt('x '+c[k],x+30,y+2,46,'#2b1d3a');});}
function bigItem(r){const k=(RUN_RES&&RUN_RES.best)||'cheese',im=RUNX.itemImg(k);if(!im||!im.complete){bigStar(r);return;}const s=r*2.3/Math.max(im.naturalWidth,im.naturalHeight);ctx.drawImage(im,-im.naturalWidth*s/2,-im.naturalHeight*s/2,im.naturalWidth*s,im.naturalHeight*s);}
function bigStar(r){starPath(r);ctx.fillStyle='#ffd23f';ctx.fill();ctx.lineWidth=r*0.095;ctx.lineJoin='round';ctx.strokeStyle='#3a2a20';ctx.stroke();starPath(r*0.5);ctx.fillStyle='#fff4b0';ctx.fill();}
function giftBox(lid){
 ctx.lineJoin='round';ctx.lineWidth=7;ctx.strokeStyle='#3a2a20';
 ctx.fillStyle='rgba(0,0,0,.22)';ctx.beginPath();ctx.ellipse(0,128,150,20,0,0,7);ctx.fill();
 ctx.fillStyle='#e63946';rr(-120,-30,240,156,14);ctx.fill();ctx.stroke();
 ctx.fillStyle='#c1121f';ctx.fillRect(-116,-26,232,22);
 ctx.fillStyle='#ffd166';ctx.fillRect(-24,-30,48,156);ctx.strokeRect(-24,-30,48,156);
 ctx.save();ctx.translate(0,-lid);ctx.rotate(lid*0.0016);
 ctx.fillStyle='#ff5a66';rr(-136,-78,272,56,14);ctx.fill();ctx.stroke();
 ctx.fillStyle='#ffd166';ctx.fillRect(-24,-78,48,56);ctx.strokeRect(-24,-78,48,56);
 for(const s of[-1,1]){ctx.beginPath();ctx.moveTo(0,-78);ctx.bezierCurveTo(s*30,-150,s*104,-140,s*84,-96);ctx.bezierCurveTo(s*70,-78,s*30,-76,0,-78);ctx.closePath();ctx.fillStyle='#ffd166';ctx.fill();ctx.stroke();}
 ctx.beginPath();ctx.arc(0,-82,15,0,7);ctx.fillStyle='#f4a93a';ctx.fill();ctx.stroke();
 ctx.restore();
}
function drawEnding(){
 const sn=typeof SLED!=='undefined'&&SLED.snap();if(sn)ctx.drawImage(sn,0,0,W,H);else drawWorld(false);
 const e=state==='ending'?stT:99;
 ctx.fillStyle='rgba(8,16,48,'+(0.74*Math.min(1,e/0.7))+')';ctx.fillRect(0,0,W,H);
 const cx=640,cy=440,ease=x=>x<0?0:x>1?1:x*x*(3-2*x);
 const z=ease((e-1.0)/0.9);                 // 0 = 페리 전체, 1 = 바구니만 크게
 const m=ease((e-3.0)/1.2);                 // 0 = 별, 1 = 선물 바구니
 // 빛줄기
 ctx.save();ctx.translate(cx,cy);ctx.rotate(t*0.35);ctx.fillStyle='rgba(255,214,102,'+(0.06+0.12*z+0.14*m)+')';
 for(let i=0;i<14;i++){ctx.rotate(Math.PI/7);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(560,-46);ctx.lineTo(560,46);ctx.closePath();ctx.fill();}ctx.restore();
 const gl=ctx.createRadialGradient(cx,cy,10,cx,cy,340);gl.addColorStop(0,'rgba(255,246,190,'+(0.3+0.45*z-0.25*m)+')');gl.addColorStop(1,'rgba(255,220,90,0)');ctx.fillStyle=gl;ctx.fillRect(cx-340,cy-340,680,680);
 // 1) 바구니를 든 페리 — 바구니 쪽으로 확대되며 사라짐
 const hA=Math.min(1,e/0.4)*(1-ease((z-0.45)/0.55));
 if(hA>0.01&&typeof RUNX!=='undefined'){RUNX.hero(ctx,cx,cy+60*(1-z),1.5+z*2.6,hA,2.3,z*34);}
 // 2) 바구니 속 큰 별 — 반짝이다가 커지고, 점점 빨리 돌다가 사라짐
 const sA=ease((z-0.45)/0.55);
 if(m<1&&sA>0){const tw=0.5+0.5*Math.sin(t*8),r=(46+z*70)*(1+0.9*m),e2=Math.max(0,e-1.9),sp=e<1.9?Math.sin(t*3)*0.12:e2*1.6+e2*e2*3.1;
  ctx.save();ctx.translate(cx,cy+(1-z)*4+Math.sin(t*3)*5*z*(1-m));ctx.globalAlpha=sA*(1-m);
  const g1=ctx.createRadialGradient(0,0,r*0.3,0,0,r*2.2);g1.addColorStop(0,'rgba(255,244,170,'+(0.5+0.35*tw)+')');g1.addColorStop(1,'rgba(255,220,90,0)');ctx.fillStyle=g1;ctx.fillRect(-r*2.2,-r*2.2,r*4.4,r*4.4);
  ctx.rotate(sp);bigItem(r);
  ctx.strokeStyle='#fff';ctx.lineCap='round';ctx.lineWidth=r*0.07;ctx.globalAlpha*=tw;for(const[a,b]of[[-1.15,-0.9],[1.2,-0.6],[0.95,1.1],[-1.05,0.95]]){ctx.beginPath();ctx.moveTo(a*r-r*0.18,b*r);ctx.lineTo(a*r+r*0.18,b*r);ctx.moveTo(a*r,b*r-r*0.18);ctx.lineTo(a*r,b*r+r*0.18);ctx.stroke();}
  ctx.restore();ctx.globalAlpha=1;}
 // 3) 선물 바구니 — 별 자리에서 돌면서 나타나 자리를 잡음
 if(m>0){const settle=ease((e-4.2)/0.5),bob=settle*Math.sin(t*2.6)*7,pop=state==='ending'?1+Math.sin(Math.min(1,Math.max(0,(e-4.1)/0.4))*Math.PI)*0.12:1;
  const lid=state==='ending'?0:Math.min(170,stT*520)+(stT>0.33?Math.sin(t*3)*6:0);
  ctx.save();ctx.translate(cx,cy+bob);ctx.rotate((1-m)*-2.6+(state==='ending'&&e>4.8?Math.sin(t*9)*0.03:0));ctx.scale((0.35+0.65*m)*pop,(0.35+0.65*m)*pop);ctx.globalAlpha=m;
  if(lid>0){const g2=ctx.createRadialGradient(0,-40,4,0,-40,190);g2.addColorStop(0,'rgba(255,255,220,.95)');g2.addColorStop(1,'rgba(255,240,150,0)');ctx.fillStyle=g2;ctx.fillRect(-200,-240,400,400);}
  giftBox(lid);ctx.restore();ctx.globalAlpha=1;}
 if(state==='ending'&&e<2.6){ctx.globalAlpha=Math.min(1,e*2)*(e>2.1?Math.max(0,(2.6-e)/0.5):1);txt('재료를 가득 모았어요!',640,110,76,'#ffd166','#c1121f',14);drawCounts(208);ctx.globalAlpha=1;}
}
return {id:'run',name:'점프 런',engine:RUNX,endBtn:5.0,
 rule:()=>'재료 <b>'+runGoal()+'개</b>를 모아<br>끝까지 달리면 <b>성공!</b><br>늑대·구덩이 조심!',
 host:{lives:()=>+(store.get('hearts')||1),goal:()=>runGoal()},
 opts:[{key:'hearts',label:'하트',small:'한 번 부딪히면 반 개씩 줄어요 · 구덩이는 바로 끝',vals:[1,2,3],def:1,fmt:v=>v+'개'},{key:'runGoal',label:'성공 기준',small:'이벤트 게이지가 차는 재료 수 (코스 전체 40개)',vals:[15,20,25,30],def:25,fmt:v=>v+'개'},{key:'runPrize',label:'증정품',small:'가장 많이 모은 재료 = 치즈볼·캔음료·새우 중 많이 모은 것 / 공통 = 위 "성공 시 증정품" 설정',vals:['most','common'],def:'most',fmt:v=>({most:'가장 많이 모은 재료',common:'공통 설정'}[v])}],
 guide(){const e=$('gGoalN');if(e)e.textContent=runGoal();},
 onResult(r){RUN_RES=r;},
 failClass:'runF',failHTML:"<img class=\"fSad\" alt=\"\" src=\"data:image/webp;base64,\"><img class=\"fWolf\" id=\"fWolf\" alt=\"\" src=\"data:image/webp;base64,\"><div class=\"wa fTitle\" data-t=\"실패!\"><b>실패!</b></div><br><div class=\"fRib\" id=\"failMsg\"></div><div class=\"fCard\"><div class=\"fTot\" id=\"fTot\"></div><div class=\"fCnts\" id=\"fCnts\"></div></div><div class=\"row\"><button class=\"btn\" id=\"retry1\">다시 도전</button><button class=\"btn\" id=\"home1\">처음으로</button></div>",
 failFill:(r,res)=>{const msg={pit:'구덩이에 빠졌어요!',hit:'하트를 모두 잃었어요!',wolf:'늑대에게 재료를 빼앗겼어요!',short:'재료가 조금 모자라요!'}[r]||'아쉬워요!';
  $('failMsg').textContent=msg;$('fWolf').style.display=(r==='pit')?'none':'block';
  const c=(res&&res.cnt)||{cheese:0,cola:0,shrimp:0};$('fTot').textContent='재료 '+((res&&res.ings)||0)+' / '+((res&&res.goal)||25);
  $('fCnts').innerHTML=['cheese','cola','shrimp'].map(k=>'<div class="fCnt"><img alt="" src="'+RUNX.itemImg(k).src+'"> x '+c[k]+'</div>').join('');
  },
 pickPrize(){return (store.get('runPrize')||'most')==='most'?'run:'+((RUN_RES&&RUN_RES.best)||'cheese'):null;},
 coupon:k=>runCoupon(k),
 ill:{cheese:'<img alt="" src="data:image/webp;base64,">',drink:'<img alt="" src="data:image/webp;base64,">',shrimp:'<img alt="" src="data:image/webp;base64,">'},
 steps:"<div class=\"step\"><span class=\"no\">1</span>\n    <svg viewBox=\"0 0 170 130\"><path d=\"M40 108h90\" stroke=\"#8aa3c8\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M60 100 Q85 18 110 100\" fill=\"none\" stroke=\"#2b4a8c\" stroke-width=\"6\" stroke-dasharray=\"10 9\" stroke-linecap=\"round\"/><circle cx=\"85\" cy=\"40\" r=\"18\" fill=\"#ffd23f\" stroke=\"#3a2a20\" stroke-width=\"4\"/><path d=\"M78 40l5 6 9-11\" fill=\"none\" stroke=\"#3a2a20\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n    <p><b>터치</b>하면 점프!<br>한 번 더 = <b>2단 점프</b><br><b>꾹 누르면</b> 날갯짓 활공</p></div>\n   <div class=\"step\"><span class=\"no\">2</span>\n    <div class=\"its\"><img alt=\"\" src=\"data:image/webp;base64,\"><img alt=\"\" src=\"data:image/webp;base64,\"><img alt=\"\" src=\"data:image/webp;base64,\"></div>\n    <p>재료 <b>3가지</b>를 모아<br><b>이벤트 게이지</b>를<br>가득 채워요</p></div>\n   <div class=\"step\"><span class=\"no\">3</span>\n    <svg viewBox=\"0 0 170 130\"><circle cx=\"85\" cy=\"58\" r=\"44\" fill=\"#fff3c4\"/><text x=\"85\" y=\"76\" text-anchor=\"middle\" font-family=\"Black Han Sans,Jua,sans-serif\" font-size=\"52\" fill=\"#e63946\" id=\"gGoalN\">25</text><text x=\"85\" y=\"124\" text-anchor=\"middle\" font-family=\"Black Han Sans,Jua,sans-serif\" font-size=\"20\" fill=\"#2b4a8c\">재료</text></svg>\n    <p id=\"gRule\"></p></div>",
 intro:drawIntro,ending:drawEnding};
})());
